-- Nexmark q5 on clink, KAFKA-SINK sink variant. Hot items: the single most-
-- bid-on auction per 10s sliding window, advancing 2s. Sliding window
-- aggregate feeding a top-1 rank. NOTE the argument orders differ and are NOT
-- interchangeable: clink is HOP(time, SIZE, SLIDE) while Flink's table
-- function is HOP(TABLE, DESCRIPTOR, SLIDE, SIZE). Getting it backwards makes
-- slide exceed size, which the operator rejects.
-- GENERATED by queries/gen_queries.py from the single cross-engine
-- definition. Edit that file, not this one.
CREATE TABLE bid (auction BIGINT, bidder BIGINT, price BIGINT, channel VARCHAR, url VARCHAR, datetime BIGINT)
  WITH (connector='kafka', format='json', brokers='__BROKERS__', topic='nx-bid',
        group_id='clink-q5-bid', auto_offset_reset='earliest',
        event_time_column='datetime', watermark_lag_ms='4001');
CREATE TABLE sink_q5 (wstart BIGINT, auction BIGINT, num BIGINT)
  WITH (connector='kafka', format='json', brokers='__BROKERS__', topic='__OUT__');
INSERT INTO sink_q5
SELECT wstart, auction, num FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY wstart ORDER BY num DESC, auction ASC) AS rn FROM (SELECT auction, COUNT(*) AS num, window_start AS wstart FROM bid GROUP BY HOP(datetime, INTERVAL '10' SECOND, INTERVAL '2' SECOND), auction) AS W) AS R WHERE rn <= 1;
